/** Leave inbox: my direct reports (HR sees all) — GET /api/v1/hr/leave-requests (who may call: holders of hr.leave.approve or hr.leave.manage). */
export function teamLeave(query?: { status?: "Pending" | "Approved" | "Rejected" | "Cancelled" }): Promise<TeamLeaveRequestOut[]> {
  return api<TeamLeaveRequestOut[]>("GET", withQuery(`/hr/leave-requests`, query), undefined);
}

/** Supervisor approves / rejects — POST /api/v1/hr/leave-requests/{leave_request_id}/decision (who may call: holders of hr.leave.approve or hr.leave.manage). */
export function decideLeave(leave_request_id: number, body: LeaveDecisionIn): Promise<LeaveRequestOut> {
  return api<LeaveRequestOut>("POST", `/hr/leave-requests/${leave_request_id}/decision`, body);
}

/** Leave balances of an employee — GET /api/v1/hr/employees/{employee_id}/leave-balances (who may call: holders of hr.leave.manage or hr.leave.approve). */
export function empBalances(employee_id: number, query?: { year?: number | null }): Promise<LeaveBalanceOut[]> {
  return api<LeaveBalanceOut[]>("GET", withQuery(`/hr/employees/${employee_id}/leave-balances`, query), undefined);
}
